contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    function test(uint256 drugs, uint256 ethAmount) public {
        // Attempt getFreeKilo before initialization should revert
        bool revertedBefore = false;
        (bool success, ) = address(c).call(abi.encodeWithSignature("getFreeKilo()"));
        if (!success) revertedBefore = true;

        // Initialize via seedMarket
        require(address(this).balance >= ethAmount, "Insufficient balance");
        c.seedMarket{value: ethAmount}(drugs);

        // Attempt getFreeKilo after seedMarket should succeed
        bool revertedAfter = false;
        (bool success2, ) = address(c).call(abi.encodeWithSignature("getFreeKilo()"));
        if (!success2) revertedAfter = true;

        assert(revertedBefore == true && revertedAfter == false);
    }

    receive() external payable {}
}

