contract InvMutTest {
    C c;
    bool public reverted1;
    bool public reverted2;

    constructor(C _c) {
        c = _c;
    }

    function test(address newCEO, address attacker) public {
        // Try setting ceoAddress first time as newCEO
        address initialCEO = c.ceoAddress();
        // We need to make 'newCEO' the ceoAddress by calling DrugDealer from it
        require(newCEO != attacker, "newCEO and attacker must differ");

        // Step 1: Make newCEO become the ceoAddress
        // For that we simulate a call from newCEO (newCEO calls DrugDealer)
        // Since we cannot change msg.sender, we first need a call that sets ceoAddress to some known address.
        // The test function's msg.sender will be this contract. So we call DrugDealer to set ceoAddress to this contract.
        c.DrugDealer();

        // Step 2: Now this contract is the ceoAddress. We try to change it to newCEO.
        // But we need to simulate call from newCEO. Cannot.
        // So we just check that a non-ceo (attacker) cannot change it while ceo can.
        // First record current ceoAddress
        address currentCEO = c.ceoAddress();
        // The ceo tries to change ceoAddress to newCEO
        c.DrugDealer();
        address afterCEO = c.ceoAddress();
        bool ceoCanChange = (afterCEO == address(this));

        // Now reset: set ceoAddress to attacker to test attacker cannot change.
        // Actually we test: if an attacker calls DrugDealer, ceoAddress does not change.
        // We cannot simulate different msg.sender, but we can compare behavior after ceoAddress is this contract,
        // and then someone else calls? No.

        // Alternate approach: we observe that on original C, only ceo can change ceoAddress.
        // On mutant M, anyone can change it.
        // So we call DrugDealer from this contract, check that ceoAddress becomes this contract (ceo can change).
        // Then we need to show that a non-ceo cannot change it. But we cannot call as a non-ceo from within this test contract.
        // However, the rule can be: calling DrugDealer always changes ceoAddress to msg.sender only if msg.sender is ceoAddress, otherwise reverts or doesn't change.
        // Since we cannot test a revert because on P it reverts (require) and on M it doesn't,
        // we can capture the distinguishability: on P, calling DrugDealer as non-ceo reverts (and ceoAddress stays same),
        // on M, calling DrugDealer as non-ceo succeeds and changes ceoAddress.
        // So we can call DrugDealer from this contract. On P, this contract is not ceoAddress initially (since ceoAddress is some other address),
        // so the call will revert. On M, it will succeed and change ceoAddress to this contract.
        // Then we assert that ceoAddress changed or not.

        // So reset: assume we start fresh. The initial ceoAddress is the hardcoded one.
        // We make a call from this contract (which is not the initial ceoAddress) to DrugDealer.
        // On P -> revert. On M -> changes ceoAddress to this contract.
        // Then we check ceoAddress after the call: if revert, it stays original; if not, it becomes this contract.
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        try c.DrugDealer() { reverted = false; } catch { reverted = true; }
        assert(reverted == (caller != c.ceoAddress()));
    }
    receive() external payable {}
}

