pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newCEO) public {
        vm.assume(caller != address(0));
        vm.assume(newCEO != address(0));
        // Get current ceoAddress before any action
        address ceoBefore = c.ceoAddress();
        // Try to change ceoAddress as caller
        vm.prank(caller);
        c.DrugDealer();
        address ceoAfter = c.ceoAddress();
        // Rule: if caller is not the previous ceo, then ceoAddress must remain unchanged
        if (caller != ceoBefore) {
            assertTrue(ceoAfter == ceoBefore);
        } else {
            // If caller is ceo, change is allowed; no assertion needed
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newCeo) public {
        vm.assume(caller != address(0));
        vm.assume(newCeo != address(0));

        // Initialize the contract to set an initial ceoAddress via the legitimate constructor-like call
        vm.prank(caller);
        c.DrugDealer();

        address oldCeo = c.ceoAddress();

        // Now perform the DrugDealer call as a different/new address
        vm.prank(newCeo);
        c.DrugDealer();

        address currentCeo = c.ceoAddress();

        // The rule: after DrugDealer(), the new ceoAddress must be newCeo iff newCeo == oldCeo, else it stays oldCeo.
        // Mutant breaks this because newCeo can become ceoAddress even when newCeo != oldCeo.
        assertTrue((newCeo == oldCeo && currentCeo == newCeo) || (newCeo != oldCeo && currentCeo == oldCeo));
    }
}
